// Package json parses JSON (RFC 8259) with a parser generated by ZeroParse from json.zp.
//
// ParseAST returns the document as typed values (Object, Array, String, Number, Bool and Null, each with
// its Span in the input), Parse returns it as a tree of Nodes, and Recognize only checks it. Decode and
// ToAny convert to the Go values that encoding/json decodes into an any.
//
// The parser accepts exactly the texts RFC 8259 defines: any value at the top level, surrounded by
// optional whitespace. Like encoding/json, it accepts invalid UTF-8 and unpaired surrogate escapes, which
// the RFC leaves to the implementation, and decodes them to U+FFFD. It rejects a byte order mark.
package json

import (
	"fmt"

	"github.com/ornew/zeroparse/parsers/json/types"
)

// Valid reports whether input is a JSON text.
func Valid(input string) bool { return Recognize(input) == nil }

// Decode parses input and returns its value as encoding/json decodes it into an any: map[string]any,
// []any, string, float64, bool or nil. As in encoding/json, the last of duplicate keys wins, and a number
// outside the range of float64 is an error.
func Decode(input string) (any, error) {
	v, err := ParseAST(input)
	if err != nil {
		return nil, err
	}
	return ToAny(v)
}

// ToAny converts a value returned by ParseAST to the Go values Decode returns.
func ToAny(v types.Value) (any, error) {
	switch v := v.(type) {
	case *types.Object:
		m := make(map[string]any, len(v.Members))
		for _, mem := range v.Members {
			x, err := ToAny(mem.Value)
			if err != nil {
				return nil, err
			}
			m[mem.Key.Value()] = x
		}
		return m, nil
	case *types.Array:
		a := make([]any, len(v.Elements))
		for i, e := range v.Elements {
			x, err := ToAny(e)
			if err != nil {
				return nil, err
			}
			a[i] = x
		}
		return a, nil
	case *types.String:
		return v.Value(), nil
	case *types.Number:
		return v.Float64()
	case *types.Bool:
		return v.Value(), nil
	case *types.Null:
		return nil, nil
	}
	return nil, fmt.Errorf("json: unexpected value %T", v)
}
